import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import { theme } from '../../../theme';
import {
  AVATAR_DEFAULT_SIZE,
  AVATAR_DEFAULT_VARIANT_TYPE,
} from './Avatar.constants';
import { StyledAvatarContainer, StyledAvatarOverlay } from './Avatar.styles';
import type { AvatarProps } from './Avatar.types';
import { resolveBackgroundColor, resolveThemeColor } from './utils';

export const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>(
  (
    {
      variantType = AVATAR_DEFAULT_VARIANT_TYPE,
      size = AVATAR_DEFAULT_SIZE,
      background,
      initialsColor,
      disabled = false,
      image,
      children = ' ',
      className,
      ...props
    },
    forwardedRef,
  ) => {
    const showImage = variantType === 'image' && Boolean(image);

    return (
      <StyledAvatarContainer
        {...omitTransientProps(props)}
        ref={forwardedRef}
        className={className}
        $size={size}
        $disabled={disabled}
        $backgroundColor={resolveBackgroundColor(background, disabled)}
        $backgroundImage={showImage ? `url(${image})` : undefined}
        $initialsColor={
          disabled
            ? theme.colors.interfaceLabelDisabled
            : resolveThemeColor(initialsColor)
        }
      >
        <StyledAvatarOverlay $disabled={disabled} $variantType={variantType}>
          {showImage ? null : children}
        </StyledAvatarOverlay>
      </StyledAvatarContainer>
    );
  },
);

Avatar.displayName = 'Avatar';
